def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n

    for _ in range(n):
        min_dist = float('inf')
        min_node = -1

        for node in range(n):
            if not visited[node] and dist[node] < min_dist:
                min_dist = dist[node]
                min_node = node

        if min_node == -1:
            break

        visited[min_node] = True

        for neighbor, weight in graph[min_node]:
            if dist[min_node] + weight < dist[neighbor]:
                dist[neighbor] = dist[min_node] + weight

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
