def solve(nums, k):
    n = len(nums)
    if n == 1:
        return nums[0]

    compressed = []
    for num in nums:
        if not compressed or num != compressed[-1]:
            compressed.append(num)

    n = len(compressed)
    if n == 1:
        return compressed[0]

    bit_tree = [0] * (n + 1)

    def update(i, val):
        i += 1
        while i <= n:
            bit_tree[i] += val
            i += i & -i

    def query(i):
        i += 1
        res = 0
        while i > 0:
            res += bit_tree[i]
            i -= i & -i
        return res

    for num in compressed:
        update(compressed.index(num), 1)

    low = 0
    high = n - 1
    ans = -float('inf')

    while low <= high:
        mid = (low + high) // 2
        count = query(mid)
        if count >= k:
            ans = compressed[mid]
            high = mid - 1
        else:
            low = mid + 1

    return ans
```

